"""Calculator definitions for Nirog.com (form markup + explainer copy). Logic lives in assets/js/tools.js."""

def nf(name, label, mn, mx, step="1", ph="", hint="", req=True):
    return ('<div class="field"><label for="f-%s">%s</label><input id="f-%s" type="number" inputmode="decimal" name="%s" min="%s" max="%s" step="%s" placeholder="%s"%s>%s</div>'
            % (name, label, name, name, mn, mx, step, ph, " required" if req else "", '<span class="hint">%s</span>' % hint if hint else ""))

def rg(name, legend, opts, cols=""):
    o = "".join('<label class="choice"><input type="radio" name="%s" value="%s"%s><span>%s</span></label>' % (name, v, " checked" if i == 0 and cols == "checkfirst" else "", t) for i, (v, t) in enumerate(opts))
    return '<fieldset class="field" style="border:0;padding:0;margin:0"><legend class="legend" style="margin-bottom:6px">%s</legend><div class="choices">%s</div></fieldset>' % (legend, o)

def sel(name, label, opts):
    o = "".join('<option value="%s">%s</option>' % (v, t) for v, t in opts)
    return '<div class="field"><label for="f-%s">%s</label><select id="f-%s" name="%s">%s</select></div>' % (name, label, name, name, o)

FTIN = '<details class="small"><summary class="muted">Know your height in feet and inches?</summary><div class="row2" data-ftin style="margin-top:8px"><div class="field"><label>Feet</label><input type="number" name="ft" min="3" max="8"></div><div class="field"><label>Inches</label><input type="number" name="in" min="0" max="11"></div></div></details>'

TOOLS = [
 {"slug": "bmi-calculator", "name": "BMI Calculator (Asian cut-offs)", "short": "BMI with the lower Indian and Asian thresholds, plus your healthy weight range.", "icon": "scale", "cat": "body",
  "title": "BMI Calculator for Indians (Asian BMI Cut-offs)", "desc": "Free BMI calculator using Indian and Asian cut-offs (overweight from 23). Get your BMI, category and healthy weight range for your height in seconds.",
  "form": '<div class="row2">' + nf("height", "Height (cm)", 90, 230, "1", "e.g. 165") + nf("weight", "Weight (kg)", 20, 250, "0.1", "e.g. 68") + "</div>" + FTIN,
  "about": "<p>Body mass index (BMI) is your weight in kilograms divided by the square of your height in metres. It is a quick screening number, not a diagnosis.</p><p>For South Asians, Indian consensus guidelines and the WHO Asia-Pacific expert group recommend lower cut-offs than the global ones: <b>18.5–22.9 is healthy, 23–24.9 is overweight and 25 or more is obesity</b>. That is because people of Indian origin tend to carry more fat around the abdomen and develop type 2 diabetes and heart disease at lower body weights.</p><p>BMI cannot tell muscle from fat, so pair it with a waist measurement. A waist over 90 cm in men or 80 cm in women signals extra risk even when BMI looks fine.</p>",
  "faqs": [("What is a healthy BMI for Indians?", "For adults of Indian origin, a BMI between 18.5 and 22.9 is considered healthy. Overweight starts at 23 and obesity at 25, which is lower than the global cut-offs of 25 and 30."),
           ("Is BMI accurate for athletes?", "No. Muscle is denser than fat, so muscular people can have a high BMI without excess body fat. Waist-to-height ratio or a body-fat test gives a better picture."),
           ("Does BMI work for children?", "Children need age- and sex-specific BMI percentile charts. This calculator is for adults aged 18 and over.")]},
 {"slug": "calorie-calculator", "name": "Calorie Calculator (BMR & TDEE)", "short": "How many calories you burn at rest and per day, with targets for loss or gain.", "icon": "flame", "cat": "food",
  "title": "Calorie Calculator: BMR and Daily Calorie Needs", "desc": "Work out your BMR and total daily calorie needs with the Mifflin-St Jeor equation, plus safe calorie targets for weight loss or weight gain.",
  "form": '<div class="row2">' + nf("age", "Age (years)", 15, 100, "1", "e.g. 34") + sel("sex", "Sex", [("male", "Male"), ("female", "Female")]) + "</div>" + '<div class="row2">' + nf("height", "Height (cm)", 90, 230, "1", "e.g. 165") + nf("weight", "Weight (kg)", 25, 250, "0.1", "e.g. 68") + "</div>" + FTIN +
          sel("activity", "Activity level", [("1.2", "Sedentary (desk job, little exercise)"), ("1.375", "Lightly active (1–3 workouts a week)"), ("1.55", "Moderately active (3–5 a week)"), ("1.725", "Very active (6–7 a week)"), ("1.9", "Extra active (physical job + training)")]),
  "about": "<p>Your basal metabolic rate (BMR) is the energy your body uses at complete rest. Multiply it by an activity factor and you get your total daily energy expenditure (TDEE): the calories that keep your weight steady.</p><p>We use the Mifflin-St Jeor equation, which research has found to be among the most accurate for adults. A deficit of about 500 kcal a day usually leads to roughly half a kilo of weight loss a week. Going much lower than that tends to backfire: hunger rises, muscle is lost and the weight returns.</p><p>Indian meals can be calorie-dense through oil, ghee, rice and sweets rather than portion size. Small swaps (less oil in the tadka, more dal and sabzi, fewer refined snacks) often matter more than skipping meals.</p>",
  "faqs": [("How accurate is a calorie calculator?", "Equations like Mifflin-St Jeor are usually within about 10% of measured values for most adults. Use the result as a starting point and adjust based on how your weight changes over 2–4 weeks."),
           ("What is the minimum safe calorie intake?", "Most adults should not go below about 1,200 kcal (women) or 1,500 kcal (men) a day without medical supervision. Very low-calorie diets need a doctor's oversight.")]},
 {"slug": "diabetes-risk-score", "name": "Diabetes Risk Score (IDRS)", "short": "The validated Indian Diabetes Risk Score: four questions, one minute.", "icon": "drop", "cat": "risk",
  "title": "Indian Diabetes Risk Score (IDRS) Calculator", "desc": "Check your type 2 diabetes risk in one minute with the Indian Diabetes Risk Score: age, waist, activity and family history. Free and private.",
  "form": rg("age", "Your age", [("0", "Under 35"), ("20", "35–49"), ("30", "50 or older")]) +
          rg("waist", "Waist size", [("0", "Women under 80 cm / men under 90 cm"), ("10", "Women 80–89 cm / men 90–99 cm"), ("20", "Women 90 cm+ / men 100 cm+")]) +
          rg("activity", "Physical activity", [("0", "Regular vigorous exercise or strenuous work"), ("10", "Regular moderate exercise or moderate work"), ("20", "Mild exercise or light work"), ("30", "No exercise and sedentary work")]) +
          rg("family", "Parents with diabetes", [("0", "Neither parent"), ("10", "One parent"), ("20", "Both parents")]),
  "about": "<p>The Indian Diabetes Risk Score (IDRS) was developed by the Madras Diabetes Research Foundation from the Chennai Urban Rural Epidemiology Study and is used in Indian screening programmes. It needs no blood test: just age, waist, activity and family history.</p><p>A score of <b>60 or more</b> means high risk, <b>30–50</b> moderate and <b>under 30</b> low. People with high scores should get a fasting blood glucose or HbA1c test. Many Indians with prediabetes have no symptoms at all, which is why screening matters.</p><p>The good news: large Indian studies have shown that regular activity and modest weight loss can delay or prevent type 2 diabetes in people at high risk. Read our <a href=\"../guides/type-2-diabetes-prevention.html\">diabetes prevention guide</a> for practical steps.</p>",
  "faqs": [("Is the IDRS a diagnosis?", "No. It estimates risk only. Diabetes is diagnosed with blood tests such as fasting plasma glucose, an oral glucose tolerance test or HbA1c."),
           ("How do I measure my waist?", "Stand relaxed, breathe out and measure around your abdomen midway between the lowest rib and the top of the hip bone, keeping the tape snug but not tight.")]},
 {"slug": "blood-pressure-checker", "name": "Blood Pressure Checker", "short": "Enter a reading to see which BP category it falls in and what to do next.", "icon": "heart", "cat": "risk",
  "title": "Blood Pressure Chart & Checker: Is My BP Normal?", "desc": "Enter your systolic and diastolic readings to see your blood pressure category (normal, elevated, stage 1 or 2) and clear next steps.",
  "form": '<div class="row2">' + nf("sys", "Systolic (top number)", 60, 260, "1", "e.g. 128", "mmHg") + nf("dia", "Diastolic (bottom number)", 30, 160, "1", "e.g. 82", "mmHg") + "</div>",
  "about": "<p>Blood pressure is written as two numbers: systolic (pressure when the heart beats) over diastolic (pressure between beats). Under the 2017 American College of Cardiology/American Heart Association guideline, <b>below 120/80 is normal, 120–129 systolic is elevated, 130–139 or 80–89 is stage 1 and 140/90 or higher is stage 2</b>. Some Indian and European guidelines still define hypertension from 140/90, so ask your doctor which targets apply to you.</p><p>High blood pressure rarely causes symptoms, yet it is a leading driver of stroke, heart attack and kidney disease in India. For an accurate home reading: sit quietly for five minutes, back supported, feet flat, arm resting at heart level, and take two readings a minute apart.</p>",
  "faqs": [("What is normal blood pressure by age?", "The healthy target for adults of all ages is generally below 120/80 mmHg. Blood pressure tends to rise with age, but that does not make higher readings harmless; your doctor may set a personal target."),
           ("When is high blood pressure an emergency?", "A reading above 180/120 with chest pain, breathlessness, severe headache, weakness, confusion or vision or speech problems needs emergency care. Call 108 or 112.")]},
 {"slug": "health-insurance-cover-calculator", "name": "Health Insurance Cover Calculator", "short": "How much health cover your family needs, plus a smart top-up suggestion.", "icon": "shield", "cat": "money",
  "title": "Health Insurance Cover Calculator: How Much Sum Insured Do I Need?", "desc": "Estimate the right health insurance sum insured for your family in India based on city, family size, age and health conditions. Free and instant.",
  "form": rg("city", "Where do you live?", [("metro", "Metro (Delhi, Mumbai, Bengaluru…)"), ("tier2", "Tier-2 city"), ("tier3", "Tier-3 town or rural")]) +
          '<div class="row2">' + nf("adults", "Adults to cover", 1, 6, "1", "e.g. 2") + nf("kids", "Children to cover", 0, 6, "1", "e.g. 1", "", False) + "</div>" +
          nf("eldest", "Age of eldest member covered", 18, 99, "1", "e.g. 42") +
          rg("ped", "Any pre-existing condition (diabetes, BP, thyroid…)?", [("no", "No"), ("yes", "Yes")]) +
          rg("parents", "Do you also want to cover parents?", [("no", "No"), ("yes", "Yes")]),
  "about": "<p>Hospital costs in Indian cities have risen sharply, and a single cardiac procedure, cancer treatment or ICU stay can run into several lakh rupees. A cover that looked generous five years ago may not be enough today.</p><p>This calculator applies a simple, transparent rule of thumb: a base amount by city type, scaled for the number of people covered, the age of the eldest member and any pre-existing conditions. It then suggests a <b>super top-up</b>, which adds a large layer of cover above a deductible for a fraction of the cost of a bigger base policy.</p><p>The number is a starting point. Policy features such as room-rent caps, co-payments, disease sub-limits and waiting periods often matter as much as the sum insured. Read our <a href=\"../guides/health-insurance-buying-guide.html\">health insurance buying checklist</a>, or request free, unbiased advice.</p>",
  "faqs": [("Is ₹5 lakh health insurance enough?", "For a single young person in a smaller city it can be a starting point, but for families in metros it is often too little. Many advisors suggest ₹10 lakh or more for metro families, plus a super top-up."),
           ("What is a super top-up?", "A super top-up policy pays once your total medical bills in a policy year cross a set deductible, such as ₹5 lakh. It is an affordable way to add a large amount of extra cover.")]},
 {"slug": "waist-to-height-ratio", "name": "Waist-to-Height Ratio", "short": "A better predictor of heart and diabetes risk than BMI alone.", "icon": "ruler", "cat": "body",
  "title": "Waist-to-Height Ratio Calculator", "desc": "Calculate your waist-to-height ratio, a strong predictor of heart disease and diabetes risk. Keep your waist under half your height.",
  "form": '<div class="row2">' + nf("waist", "Waist (cm)", 40, 200, "0.5", "e.g. 86") + nf("height", "Height (cm)", 90, 230, "1", "e.g. 165") + "</div>" + FTIN,
  "about": "<p>Fat stored around the abdomen (visceral fat) is closely linked to insulin resistance, high blood pressure and heart disease. Waist-to-height ratio captures this better than BMI, and the message is simple for everyone: <b>keep your waist to less than half your height</b>.</p><p>A ratio of 0.5–0.59 means increased risk and 0.6 or above means high risk. This measure is especially useful for South Asians, who often carry abdominal fat even at a normal weight.</p>",
  "faqs": [("What is a good waist-to-height ratio?", "Between 0.4 and 0.49 is generally considered healthy for adults. Above 0.5 indicates increased cardiometabolic risk."),
           ("Where should I measure my waist?", "Midway between the bottom of your lowest rib and the top of your hip bone, after breathing out normally.")]},
 {"slug": "ideal-weight-calculator", "name": "Ideal Weight Calculator", "short": "Your healthy weight range for your height, using Asian BMI ranges.", "icon": "target", "cat": "body",
  "title": "Ideal Weight Calculator by Height (Asian BMI Range)", "desc": "Find your healthy weight range for your height using the Asian BMI range of 18.5–22.9, with a practical mid-range target weight.",
  "form": nf("height", "Height (cm)", 90, 230, "1", "e.g. 165") + FTIN,
  "about": "<p>There is no single perfect weight. A healthy range for adults of Indian origin corresponds to a BMI of roughly 18.5–22.9. Within that range, your best weight is one you can maintain while eating well, staying active and keeping a healthy waist size.</p><p>If you are above the range, losing even 5–10% of your body weight can lower blood sugar, blood pressure and liver fat in a meaningful way.</p>",
  "faqs": [("Is ideal weight different for men and women?", "The BMI-based healthy range is the same for adult men and women. Body composition differs, so waist size and fitness are useful extra checks.")]},
 {"slug": "water-intake-calculator", "name": "Water Intake Calculator", "short": "A daily water target adjusted for your weight, exercise and climate.", "icon": "drop", "cat": "food",
  "title": "Water Intake Calculator: How Much Water Should I Drink?", "desc": "Estimate how much water you need each day based on your weight, exercise and climate, including hot Indian summers. Simple and free.",
  "form": nf("weight", "Weight (kg)", 20, 250, "0.1", "e.g. 68") + nf("exercise", "Exercise per day (minutes)", 0, 300, "5", "e.g. 30", "", False) + rg("climate", "Climate", [("normal", "Moderate"), ("hot", "Hot or humid")]),
  "about": "<p>Fluid needs vary with body size, activity, heat and diet. A practical starting point for healthy adults is around 30–35 ml per kilogram of body weight, plus extra during exercise and hot weather.</p><p>Thirst and urine colour are good everyday guides: pale yellow usually means you are well hydrated. In Indian summers, add an extra glass or two and include salt-containing fluids such as nimbu pani or buttermilk if you sweat heavily.</p>",
  "faqs": [("Do tea and coffee count towards water intake?", "Yes. Tea, coffee, milk, buttermilk, soups and water-rich foods all contribute. Caffeine has only a mild diuretic effect in regular drinkers.")]},
 {"slug": "heart-rate-zones", "name": "Heart Rate Zone Calculator", "short": "Your maximum heart rate and five training zones for safe, effective exercise.", "icon": "gauge", "cat": "fitness",
  "title": "Heart Rate Zone Calculator (Max HR and Training Zones)", "desc": "Calculate your maximum heart rate and five training zones using the Tanaka formula and optional resting pulse (Karvonen method).",
  "form": '<div class="row2">' + nf("age", "Age (years)", 10, 99, "1", "e.g. 40") + nf("rest", "Resting pulse (optional)", 30, 120, "1", "e.g. 68", "beats per minute", False) + "</div>",
  "about": "<p>Training by heart rate helps you exercise hard enough to improve fitness without overdoing it. We estimate maximum heart rate with the Tanaka formula (208 − 0.7 × age), which is more accurate for older adults than the classic 220 − age.</p><p>If you add your resting pulse (measure it in the morning before getting up), we use the Karvonen method, which tailors zones to your fitness. Most health benefits come from moderate exercise in zones 2–3: brisk walking, cycling or swimming where you can talk but not sing.</p>",
  "faqs": [("What heart rate is moderate exercise?", "Roughly 64–76% of your maximum heart rate. A simple check: you can talk in full sentences but cannot sing.")]},
 {"slug": "protein-calculator", "name": "Protein Calculator", "short": "How much protein you need a day, with Indian food equivalents.", "icon": "bowl", "cat": "food",
  "title": "Protein Calculator: Daily Protein Needs with Indian Foods", "desc": "Calculate your daily protein requirement by body weight and goal, with practical Indian vegetarian and non-vegetarian food equivalents.",
  "form": nf("weight", "Weight (kg)", 20, 250, "0.1", "e.g. 68") + sel("goal", "Your goal", [("0.83", "Healthy adult (ICMR requirement)"), ("1.0", "Over 60, or recovering"), ("1.2", "Losing weight / regular exercise"), ("1.6", "Strength training to build muscle")]),
  "about": "<p>Protein supports muscle, immunity and healthy ageing. ICMR-NIN sets the requirement for healthy Indian adults at about 0.83 g per kilogram of body weight per day. Many Indian diets fall short because meals are built around cereals.</p><p>Easy ways to add protein: an extra katori of dal, curd or buttermilk with lunch, paneer or tofu in sabzi, sprouts or roasted chana as snacks, and eggs, fish or chicken if you eat them. Spread protein across meals rather than loading it into dinner.</p>",
  "faqs": [("Can vegetarians get enough protein?", "Yes. Combining cereals with pulses (dal-rice, rajma-chawal, idli-sambar), adding dairy, soy, nuts and seeds meets most people's needs.")]},
 {"slug": "due-date-calculator", "name": "Pregnancy Due Date Calculator", "short": "Estimated due date and how many weeks along you are.", "icon": "baby", "cat": "family",
  "title": "Pregnancy Due Date Calculator (EDD by Last Period)", "desc": "Calculate your estimated due date (EDD) and current week of pregnancy from the first day of your last period and cycle length.",
  "form": '<div class="field"><label for="f-lmp">First day of your last period</label><input id="f-lmp" type="date" name="lmp" required></div>' + nf("cycle", "Average cycle length (days)", 21, 40, "1", "28", "", False),
  "about": "<p>Doctors estimate the due date by adding 280 days (40 weeks) to the first day of the last menstrual period, adjusted if your cycle is longer or shorter than 28 days. An early ultrasound gives the most accurate date.</p><p>Register your pregnancy early with your doctor or the nearest government health centre for antenatal check-ups, iron and folic acid, tetanus vaccination and scans.</p>",
  "faqs": [("How accurate is a due date?", "It is an estimate. Only a small share of babies arrive exactly on the due date; most are born within two weeks either side.")]},
 {"slug": "sleep-calculator", "name": "Sleep Calculator", "short": "The best times to go to bed so you wake up between sleep cycles.", "icon": "moon", "cat": "fitness",
  "title": "Sleep Calculator: What Time Should I Go to Bed?", "desc": "Find the best bedtime for your wake-up time based on 90-minute sleep cycles, so you wake up feeling refreshed instead of groggy.",
  "form": '<div class="field"><label for="f-wake">I want to wake up at</label><input id="f-wake" type="time" name="wake" value="06:30" required></div>',
  "about": "<p>Sleep runs in cycles of roughly 90 minutes. Waking at the end of a cycle, rather than in the middle of deep sleep, can help you feel more alert. Adults generally need 7 or more hours a night; teenagers need more.</p><p>Consistency matters more than any single night: try to keep the same wake-up time every day, including weekends. Read our <a href=\"../guides/better-sleep.html\">sleep guide</a> for habits that help.</p>",
  "faqs": [("How many hours of sleep do adults need?", "Most adults need at least 7 hours of sleep a night. Regularly sleeping less is linked to weight gain, high blood pressure, diabetes and poor mood.")]},
]
